#!/usr/bin/env tsx
import { readFile, readdir, writeFile } from 'node:fs/promises'
import { join } from 'node:path'
import { parseEnv } from 'node:util'
import { dirs } from '../src/dirs'
import { getConsistentKey } from './is-key-consistent'

const environments = await readdir(dirs.envs)

const envs = await Promise.all(
  environments.map(async environment => {
    const file = join(dirs.envs, environment, '.env')
    const content = await readFile(file, 'utf-8')
    return parseEnv(content) as Record<string, string>
  })
)

await writeFile(
  join(dirs.src, 'env-type.ts'),
  // language=TypeScript
  `
    /**
     * This file is auto-generated by @platform/env.
     * DO NOT EDIT THIS FILE MANUALLY.
     */
    export type EnvType = Readonly<{
      ENVIRONMENT: ${environments.map(environment => `'${environment}'`).join('|')}
      ${getConsistentKey(envs)
        .map(key => `${key}: string`)
        .join(';')}
    }>
  `
)
